BEGIN;
CREATE TABLE admin_notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title varchar(160) NOT NULL,message varchar(2000) NOT NULL,target_type varchar(16) NOT NULL CHECK(target_type IN('active','course','session','students')),target_value varchar(160),target_snapshot jsonb NOT NULL DEFAULT '{}',recipient_count integer NOT NULL CHECK(recipient_count>0),status varchar(16) NOT NULL DEFAULT 'saved' CHECK(status IN('saved','archived')),created_by uuid REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_notice_recipients(notice_id uuid NOT NULL REFERENCES admin_notices(id),student_id uuid NOT NULL REFERENCES students(id),portal_status varchar(24) NOT NULL DEFAULT 'portal-saved',whatsapp_status varchar(24) NOT NULL DEFAULT 'not-requested',saved_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,PRIMARY KEY(notice_id,student_id));
CREATE INDEX admin_notice_history_idx ON admin_notices(created_at DESC,id);
CREATE INDEX admin_notice_student_idx ON admin_notice_recipients(student_id,saved_at DESC);
CREATE TABLE due_reminder_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),due_date date NOT NULL,amount_paise bigint NOT NULL CHECK(amount_paise>0),due_status varchar(16) NOT NULL CHECK(due_status IN('due-soon','overdue')),delivery_status varchar(24) NOT NULL DEFAULT 'history-only',whatsapp_status varchar(24) NOT NULL DEFAULT 'not-requested',recorded_by uuid REFERENCES app_users(id),recorded_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX due_reminder_student_idx ON due_reminder_history(student_id,recorded_at DESC);
CREATE TABLE certificates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),certificate_type varchar(40) NOT NULL CHECK(certificate_type IN('main','data-entry','ms-office','accounting-tally')),certificate_number varchar(100) NOT NULL UNIQUE,issue_date date NOT NULL,threshold_percent integer NOT NULL CHECK(threshold_percent IN(40,50,60,100)),status varchar(16) NOT NULL DEFAULT 'issued',print_status varchar(32) NOT NULL DEFAULT 'layout-pending',issued_by uuid REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(student_id,certificate_type));
CREATE INDEX certificates_student_idx ON certificates(student_id,issue_date DESC);
CREATE TABLE id_card_issues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),issue_date date NOT NULL,status varchar(16) NOT NULL DEFAULT 'issued' CHECK(status IN('issued','printed')),print_count integer NOT NULL DEFAULT 0 CHECK(print_count>=0),last_printed_at timestamptz,print_layout_status varchar(40) NOT NULL DEFAULT 'authoritative-layout-pending',issued_by uuid REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX id_card_student_idx ON id_card_issues(student_id,created_at DESC);
COMMIT;
